import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import vm from 'node:vm'
import ts from '../app/node_modules/typescript/lib/typescript.js'
import { deriveCurriculumMaturity } from '../app/scripts/generateCurriculumQualityStatus.ts'

const sha = (bytes: Buffer | string) => createHash('sha256').update(bytes).digest('hex')
const bind = (path: string) => ({ path, rawSha256: sha(readFileSync(path)) })
const load = (path: string) => JSON.parse(readFileSync(path, 'utf8'))
const implementation = 'app/scripts/generateCurriculumQualityStatus.ts'
const text = readFileSync(implementation, 'utf8')
const names = ['normalizeExamTextForInspection', 'hasExamSubtaskMarkers', 'hasScoringStructure', 'hasBlockingExamReviewStatus', 'isPlaceholderExamData', 'concreteExamReadinessIssues', 'stringArray', 'examReleaseCoverageIssues', 'deriveScopeMaturity']
const functions = names.map(name => {
  const start = text.indexOf('function ' + name + '(')
  assert(start >= 0)
  const end = text.indexOf('\n}\n', start)
  assert(end > start)
  return text.slice(start, end + 2)
}).join('\n')
const context: any = {}
vm.runInNewContext(ts.transpileModule(functions + '\nthis.native = {' + names.join(',') + '};', {
  compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.None },
}).outputText, context)
const native = context.native
const infoPath = 'curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_INFORMATIK.de.json'
assert.equal(bind(infoPath).rawSha256, '93a653b110949ff410a73bd750b2a605a9ab0329fe1cd157f016869d848e1f7e')
const info = load(infoPath)
const six = info.goals.filter((goal: any) => goal.extendedData?.routeTerminal && goal.examData)
assert.equal(six.length, 6)
const solution = six[0].examData.solutionContent
const tail = six[0].examData.taskContent.slice(six[0].examData.taskContent.indexOf('. ') + 2)
assert(six.every((goal: any) => goal.examData.solutionContent === solution && goal.examData.taskContent.endsWith(tail)))
const signatures = six.map((goal: any) => ({
  goalId: goal.id,
  task: goal.examData.taskContent,
  solution: goal.examData.solutionContent,
  taskSha256: sha(goal.examData.taskContent),
  solutionSha256: sha(goal.examData.solutionContent),
}))
const sources: any[] = []
const rows: any[] = []
for (const file of readdirSync('curricula/DE/Gymnasium/canonical').filter(name => name.endsWith('.json')).sort()) {
  const path = 'curricula/DE/Gymnasium/canonical/' + file
  const landscape = load(path)
  if (typeof landscape.landscapeId !== 'string' || !Array.isArray(landscape.goals)) continue
  sources.push({ ...bind(path), landscapeId: landscape.landscapeId, title: landscape.title, goalCount: landscape.goals.length })
  for (const goal of landscape.goals.filter((goal: any) => goal.examData)) {
    const exam = goal.examData
    const task = typeof exam.taskContent === 'string' ? exam.taskContent : ''
    const sameTask = signatures.filter((signature: any) => task === signature.task)
    // This is the actual full fixed boilerplate grammar, not a length or digit heuristic.
    const familyPrefix = /^Bearbeiten Sie eine materialgestützte [^.]+-Aufgabe zu [^.]+\. /u
    const familyMatch = familyPrefix.test(task) && task.slice(task.indexOf('. ') + 2) === tail
      && exam.solutionContent === solution
    rows.push({
      sourcePath: path, landscapeId: landscape.landscapeId, landscapeTitle: landscape.title,
      goalId: goal.id, title: goal.title, routeTerminal: goal.extendedData?.routeTerminal === true,
      reviewStatus: exam.reviewStatus ?? null,
      readinessIssues: Array.from(native.concreteExamReadinessIssues(goal)),
      releaseCoverageIssues: Array.from(native.examReleaseCoverageIssues(goal)),
      placeholderDetected: native.isPlaceholderExamData(goal),
      recognizedSubtaskMarkers: native.hasExamSubtaskMarkers(native.normalizeExamTextForInspection(task)),
      matchesExactInfoTaskSignatures: sameTask.map((signature: any) => signature.goalId),
      matchesFullGenericTaskAndSolutionFamily: familyMatch,
      sameGenericSolutionOnly: exam.solutionContent === solution,
      taskSha256: sha(task), solutionSha256: sha(String(exam.solutionContent ?? '')),
      matchedFullTaskAndSolution: familyMatch || sameTask.length > 0 ? { task, solution: exam.solutionContent } : null,
    })
  }
}
assert.equal(sources.length, 21)
const reportPath = 'docs/qa-ci/status/curriculum-quality-status.json'
const report = load(reportPath)
const maturity: any[] = []
for (const curriculum of report.curricula) {
  const scopes = curriculum.scopes.map((scope: any) => ({
    scopeId: scope.scopeId,
    recordedMaturity: scope.maturity,
    derivedFromActualCurrentScopeRules: native.deriveScopeMaturity(scope.rules),
    cqr202: scope.rules.find((rule: any) => rule.id === 'CQR-202') ?? null,
    cqr203: scope.rules.find((rule: any) => rule.id === 'CQR-203') ?? null,
    hypotheticalCqr202WarningMaturity: native.deriveScopeMaturity(scope.rules.map((rule: any) =>
      rule.id === 'CQR-202' ? { ...rule, status: 'warn' } : rule)),
  }))
  assert(scopes.every((scope: any) => scope.recordedMaturity === scope.derivedFromActualCurrentScopeRules))
  const actualDerived = deriveCurriculumMaturity(curriculum.rules, curriculum.scopes, curriculum.landscapeId)
  assert.equal(actualDerived, curriculum.maturity)
  const hypotheticalScopes = curriculum.scopes.map((scope: any) => ({
    ...scope,
    rules: scope.rules.map((rule: any) => rule.id === 'CQR-202' ? { ...rule, status: 'warn' } : rule),
    maturity: native.deriveScopeMaturity(scope.rules.map((rule: any) =>
      rule.id === 'CQR-202' ? { ...rule, status: 'warn' } : rule)),
  }))
  maturity.push({
    landscapeId: curriculum.landscapeId, title: curriculum.title,
    recordedMaturity: curriculum.maturity, derivedFromActualStoredRules: actualDerived,
    hypotheticalAllOwnCqr202WarningsMaturity: deriveCurriculumMaturity(curriculum.rules, hypotheticalScopes, curriculum.landscapeId),
    scopes,
  })
}
const result = {
  status: 'READ-ONLY-current-native-all-canonical-exam-census-not-content-approval',
  implementations: [bind(implementation)], sourceCount: sources.length, sources, examDataCount: rows.length,
  sixExactInfoSignatures: signatures,
  fullGenericFamilyDefinition: { fixedTaskTail: tail, exactSolution: solution, prefixGrammar: '^Bearbeiten Sie eine materialgestützte [^.]+-Aufgabe zu [^.]+\\. ' },
  summaryByLandscape: sources.map(source => {
    const exams = rows.filter(row => row.landscapeId === source.landscapeId)
    return {
      landscapeId: source.landscapeId, title: source.title, examDataCount: exams.length,
      readinessIssueCount: exams.filter(row => row.readinessIssues.length > 0).length,
      releaseCoverageIssueCount: exams.filter(row => row.releaseCoverageIssues.length > 0).length,
      detectedPlaceholders: exams.filter(row => row.placeholderDetected).length,
      exactInfoTaskMatches: exams.filter(row => row.matchesExactInfoTaskSignatures.length > 0).length,
      fullGenericFamilyMatches: exams.filter(row => row.matchesFullGenericTaskAndSolutionFamily).length,
      sameGenericSolution: exams.filter(row => row.sameGenericSolutionOnly).length,
    }
  }),
  rows, generatedStatusBinding: bind(reportPath), generatedStatusDate: report.generatedAt,
  actualMaturityDerivation: maturity,
  maturityBoundary: 'The unchanged native scope and curriculum derivations consume actual stored report rules; all21 reproduced. CQR202 warn reduces an otherwise ready scope toM2. Hypothetical warnings are labeled and do not claim an actual new central generator run, current-source freshness, or machine content correctness. Earlier failing graph/other gates can mask the additional defect at curriculum level.',
}
writeFileSync('tmp/canonical-exam-readiness-census.json', JSON.stringify(result, null, 2) + '\n')
console.log(JSON.stringify({ sources: sources.length, exams: rows.length, byLandscape: result.summaryByLandscape,
  infoMaturity: maturity.find(row => row.landscapeId === info.landscapeId),
  genericMatchedSubjects: result.summaryByLandscape.filter(row => row.fullGenericFamilyMatches),
}))
